-- Prebuilt tiles, phase 1 (docs/PREBUILT-TILES.md step 1): the far ring's tiles without decor and the
-- 5 km horizon blocks, generated by the exporter with this mod's own Lua (earthng/bake_tiles.py runs
-- native.lua under LuaJIT) and read back here instead of being generated while driving. This file is
-- the codec only; native.lua decides when a baked layer is used (BAKED) and falls back to the generator
-- for any tile that is missing, stale or unreadable.
--
-- A cell file (one per 1 km source cell, the cell of a layer's south-west corner):
--   file    := 'EGK1' u(version) u(count) count * (u(#key) key u(length)) payloads
--   payload := value (below), one per key: 'far:<i>_<j>', 'h1000:<bi>_<bj>', 'h500:<i>_<j>'
-- A value is a tagged tree of the manifest as native.lua keeps it. Numbers are LEB128 varints, signed
-- ones zigzagged. A mesh (a table with verts, normals, uvs and faces) is packed: positions in mm,
-- normals in 1e-4, UVs in 1/4096 of a repeat, each delta-coded on the previous one; faces are their
-- {v, n, u} indices, delta-coded. mm and 1e-4 are the collector's own weld quanta (generator.lua
-- vertexIndex, normalIndex), so no two values it keeps apart are merged; a UV moves 1/8192 of a
-- repeat at most (3 mm on the 24 m ground). The ZIP's deflate does the general compression.
local M = {}
local byte, char, sub, floor, concat = string.byte, string.char, string.sub, math.floor, table.concat
M.MAGIC = 'EGK1'
M.FORMAT = 'earthng-baked-v1'
M.VERSION = 1
local MM, NQ, UQ = 1000, 10000, 4096
local T_FALSE, T_TRUE, T_INT, T_NUM, T_STR, T_REF, T_ARRAY, T_MAP, T_MESH = 0, 1, 2, 3, 4, 5, 6, 7, 8
local MESH_KEYS = {verts = true, normals = true, uvs = true, faces = true}

-- ---------------------------------------------------------------------------------------------------
-- Encoding (the exporter's bake; not called in the game)
-- ---------------------------------------------------------------------------------------------------
local function finite(v) return type(v) == 'number' and v == v and v ~= math.huge and v ~= -math.huge end

local function writer()
  local buf, n, strings, count = {}, 0, {}, 0
  local w = {}
  function w.u(value)
    if value < 0 or value ~= floor(value) then error('bake: not an unsigned integer: ' .. tostring(value)) end
    while value >= 128 do
      local low = value % 128
      n = n + 1; buf[n] = low + 128
      value = (value - low) / 128
    end
    n = n + 1; buf[n] = value
  end
  function w.s(value) w.u(value >= 0 and value * 2 or -value * 2 - 1) end
  function w.q(value, scale)
    if not finite(value) then error('bake: non-finite mesh number') end
    return floor(value * scale + .5)
  end
  function w.raw(text)
    for k = 1, #text do n = n + 1; buf[n] = byte(text, k) end
  end
  function w.str(text)
    local index = strings[text]
    if index then w.u(T_REF); w.u(index); return end
    count = count + 1
    strings[text] = count
    w.u(T_STR); w.u(#text); w.raw(text)
  end
  function w.done()
    local parts = {}
    for first = 1, n, 4096 do parts[#parts + 1] = char(unpack(buf, first, math.min(n, first + 4095))) end
    return concat(parts)
  end
  return w
end

local function isArray(t)
  local count = 0
  for k in pairs(t) do
    if type(k) ~= 'number' or k < 1 or k ~= floor(k) then return false end
    count = count + 1
  end
  return count == #t
end

local function sortedKeys(t)
  local keys = {}
  for k in pairs(t) do keys[#keys + 1] = k end
  table.sort(keys, function(a, b)
    local ta, tb = type(a), type(b)
    if ta ~= tb then return ta < tb end
    return a < b
  end)
  return keys
end

local value

local function mesh(w, m)
  local verts, normals, uvs, faces = m.verts, m.normals or {}, m.uvs or {}, m.faces
  w.u(#verts)
  local px, py, pz = 0, 0, 0
  for k = 1, #verts do
    local p = verts[k]
    local x, y, z = w.q(p.x, MM), w.q(p.y, MM), w.q(p.z or 0, MM)
    w.s(x - px); w.s(y - py); w.s(z - pz)
    px, py, pz = x, y, z
  end
  w.u(#normals)
  px, py, pz = 0, 0, 0
  for k = 1, #normals do
    local p = normals[k]
    local x, y, z = w.q(p.x, NQ), w.q(p.y, NQ), w.q(p.z, NQ)
    w.s(x - px); w.s(y - py); w.s(z - pz)
    px, py, pz = x, y, z
  end
  w.u(#uvs)
  px, py = 0, 0
  for k = 1, #uvs do
    local p = uvs[k]
    local x, y = w.q(p.u, UQ), w.q(p.v, UQ)
    w.s(x - px); w.s(y - py)
    px, py = x, y
  end
  w.u(#faces)
  px, py, pz = 0, 0, 0
  for k = 1, #faces do
    local f = faces[k]
    w.s(f.v - px); w.s(f.n - py); w.s(f.u - pz)
    px, py, pz = f.v, f.n, f.u
  end
  -- the rest of the mesh table (its material) as a map
  local rest = {}
  for key, v in pairs(m) do if not MESH_KEYS[key] then rest[key] = v end end
  value(w, rest)
end

local function isMesh(t)
  return type(t.verts) == 'table' and type(t.faces) == 'table'
    and (t.normals == nil or type(t.normals) == 'table') and (t.uvs == nil or type(t.uvs) == 'table')
end

value = function(w, v)
  local kind = type(v)
  if kind == 'boolean' then w.u(v and T_TRUE or T_FALSE)
  elseif kind == 'number' then
    if not finite(v) then error('bake: non-finite number') end
    if v == floor(v) and math.abs(v) < 2 ^ 52 then w.u(T_INT); w.s(v)
    else
      -- '%.17g' gives the double back exactly (the few such numbers are positions and rectangles)
      local text = string.format('%.17g', v)
      w.u(T_NUM); w.u(#text); w.raw(text)
    end
  elseif kind == 'string' then w.str(v)
  elseif kind == 'table' then
    if isMesh(v) then w.u(T_MESH); mesh(w, v)
    elseif isArray(v) then
      w.u(T_ARRAY); w.u(#v)
      for k = 1, #v do value(w, v[k]) end
    else
      local keys = sortedKeys(v)
      w.u(T_MAP); w.u(#keys)
      for _, key in ipairs(keys) do value(w, key); value(w, v[key]) end
    end
  else
    error('bake: cannot store a ' .. kind)
  end
end

-- A manifest (any tree of booleans, numbers, strings and tables) as bytes.
function M.encode(v)
  local w = writer()
  value(w, v)
  return w.done()
end

-- A cell file of {key = payload bytes}.
function M.file(payloads)
  local keys = sortedKeys(payloads)
  local w = writer()
  w.raw(M.MAGIC)
  w.u(M.VERSION)
  w.u(#keys)
  for _, key in ipairs(keys) do
    w.u(#key); w.raw(key); w.u(#payloads[key])
  end
  for _, key in ipairs(keys) do w.raw(payloads[key]) end
  return w.done()
end

-- ---------------------------------------------------------------------------------------------------
-- Decoding (the game)
-- ---------------------------------------------------------------------------------------------------
local function reader(data, pos, last)
  local r = {}
  function r.u()
    local result, mul = 0, 1
    while true do
      if pos > last or mul > 2 ^ 49 then error('truncated baked tile') end
      local b = byte(data, pos)
      pos = pos + 1
      if b < 128 then return result + b * mul end
      result, mul = result + (b - 128) * mul, mul * 128
    end
  end
  function r.s()
    local u = r.u()
    return u % 2 == 0 and u / 2 or -(u + 1) / 2
  end
  function r.bytes(length)
    if pos + length - 1 > last then error('truncated baked tile') end
    local text = sub(data, pos, pos + length - 1)
    pos = pos + length
    return text
  end
  function r.at() return pos end
  return r
end

-- Byte ranges {key = {first, last}} of a cell file (1-based, inclusive).
function M.index(data)
  if type(data) ~= 'string' or sub(data, 1, 4) ~= M.MAGIC then error('not an EarthNG baked cell') end
  local r = reader(data, 5, #data)
  if r.u() ~= M.VERSION then error('baked cell version') end
  local count, entries = r.u(), {}
  if count > 4096 then error('too many baked layers in a cell') end
  for k = 1, count do
    local key = r.bytes(r.u())
    entries[k] = {key, r.u()}
  end
  local out, at = {}, r.at()
  for _, e in ipairs(entries) do
    if out[e[1]] then error('duplicate baked layer: ' .. e[1]) end
    out[e[1]] = {at, at + e[2] - 1}
    at = at + e[2]
  end
  if at - 1 ~= #data then error('baked cell size does not match its index') end
  return out
end

-- The value stored at data[first..last]. pause() is called every few hundred vertices.
function M.decode(data, first, last, pause)
  local r = reader(data, first, last)
  local u, s = r.u, r.s
  local strings, count, work = {}, 0, 0
  local function step(n)
    work = work + n
    if work >= 512 then work = 0; if pause then pause() end end
  end
  local read
  local function readMesh()
    local verts, normals, uvs, faces = {}, {}, {}, {}
    local x, y, z = 0, 0, 0
    for k = 1, u() do
      x, y, z = x + s(), y + s(), z + s()
      verts[k] = {x = x / MM, y = y / MM, z = z / MM}
      step(1)
    end
    x, y, z = 0, 0, 0
    for k = 1, u() do
      x, y, z = x + s(), y + s(), z + s()
      normals[k] = {x = x / NQ, y = y / NQ, z = z / NQ}
      step(1)
    end
    x, y = 0, 0
    for k = 1, u() do
      x, y = x + s(), y + s()
      uvs[k] = {u = x / UQ, v = y / UQ}
      step(1)
    end
    -- a corner seen again reuses its face table, as the collector's fmap does
    local seen = {}
    x, y, z = 0, 0, 0
    for k = 1, u() do
      x, y, z = x + s(), y + s(), z + s()
      local key = (x < 2097152 and y < 65536 and z < 65536) and (x * 65536 + y) * 65536 + z or nil
      local face = key and seen[key]
      if not face then
        face = {v = x, n = y, u = z}
        if key then seen[key] = face end
      end
      faces[k] = face
      step(1)
    end
    local m = read()
    if type(m) ~= 'table' then error('invalid baked mesh') end
    m.verts, m.normals, m.uvs, m.faces = verts, normals, uvs, faces
    return m
  end
  read = function()
    local tag = u()
    if tag == T_FALSE then return false
    elseif tag == T_TRUE then return true
    elseif tag == T_INT then return s()
    elseif tag == T_NUM then
      local v = tonumber(r.bytes(u()))
      if not v then error('invalid baked number') end
      return v
    elseif tag == T_STR then
      local text = r.bytes(u())
      count = count + 1
      strings[count] = text
      return text
    elseif tag == T_REF then
      local text = strings[u()]
      if not text then error('invalid baked string reference') end
      return text
    elseif tag == T_ARRAY then
      local out = {}
      for k = 1, u() do out[k] = read() end
      return out
    elseif tag == T_MAP then
      local out = {}
      for _ = 1, u() do
        local key = read()
        out[key] = read()
      end
      return out
    elseif tag == T_MESH then
      return readMesh()
    end
    error('invalid baked tag ' .. tostring(tag))
  end
  local v = read()
  if r.at() ~= last + 1 then error('baked layer size does not match its value') end
  return v
end

-- ---------------------------------------------------------------------------------------------------
-- Staleness: a digest of the Lua and the climate blocks a bake was made with
-- ---------------------------------------------------------------------------------------------------
-- The files whose change can change a far or horizon layer (the planet ZIP's paths).
M.CODE = {'/lua/ge/extensions/e2r/generator.lua', '/lua/ge/extensions/e2r/sweep.lua',
  '/lua/ge/extensions/e2r/biome.lua', '/lua/ge/extensions/e2r/cellformat.lua',
  '/lua/ge/extensions/e2r/roads3.lua', '/lua/ge/extensions/e2r/native.lua',
  '/lua/ge/extensions/e2r/coordinates.lua', '/lua/ge/extensions/e2r/bake.lua'}

-- FNV-1a (32 bit) and the length of the bytes without carriage returns, so a CRLF and an LF checkout
-- of the same file agree. 'missing' for nil. pause() every 64 kB.
function M.digest(data, pause)
  if type(data) ~= 'string' then return 'missing' end
  local bxor, tobit, lshift = bit.bxor, bit.tobit, bit.lshift
  local h, length = tobit(2166136261), 0
  for first = 1, #data, 65536 do
    for k = first, math.min(#data, first + 65535) do
      local b = byte(data, k)
      if b ~= 13 then
        h = bxor(h, b)
        -- h * 16777619 mod 2^32, exact in doubles: 16777619 = 2^24 + 403
        h = tobit(lshift(h, 24) + h * 403)
        length = length + 1
      end
    end
    if pause then pause() end
  end
  return string.format('%08x:%d', h % 4294967296, length)
end

return M
